INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('hotel-del-coronado', 'Hotel del Coronado', 'San Diego', '🏖️', 'USA', 'Comedy', '😂', '1950s', ARRAY['Some Like It Hot']::text[], 'The grand Victorian beach hotel that stood in for Florida in the 1959 classic.', 'Opened in 1888, the Hotel del Coronado is a wooden Victorian beach resort with its famous red-roofed turrets. Its beachfront and wide verandas gave Some Like It Hot its sunny Florida look.', 'https://www.booking.com/hotel/us/hotel-del-coronado.html', 'https://upload.wikimedia.org/wikipedia/commons/a/a8/2019_Hotel_del_Coronado_from_beach.jpg', 'Beyond My Ken (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#e07a5f,#c14f36)')
