INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('park-hyatt-tokyo', 'Park Hyatt Tokyo', 'Tokyo', '🗼', 'Japan', 'Drama', '🎞️', '2000s', ARRAY['Lost in Translation']::text[], 'The New York Bar on the 52nd floor, where Bob and Charlotte first meet.', 'On the top floors of the Shinjuku Park Tower, the Park Hyatt has looked over Tokyo since the 1990s. Its high-floor New York Bar and glass-walled views are the quiet, jet-lagged heart of Lost in Translation.', 'https://www.booking.com/hotel/jp/park-hyatt-tokyo.html', 'https://upload.wikimedia.org/wikipedia/commons/1/11/ParkHyattTokyoFront.JPG', 'moore (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#7d8ca3,#3f4b5e)')
