INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('fairmont-chateau-frontenac', 'Fairmont Le Château Frontenac', 'Quebec City', '🏰', 'Canada', 'Thriller', '🔪', '1950s', ARRAY['I Confess']::text[], 'Alfred Hitchcock used Quebec City''s Old Town and this castle-like landmark''s dramatic silhouette throughout his 1953 thriller.', 'Opened in 1893 above the St. Lawrence River, Château Frontenac dominates the Quebec City skyline. Its copper-roofed silhouette is the landmark Hitchcock used to ground I Confess in the city.', 'https://www.booking.com/hotel/ca/fairmont-chateau-frontenac.html', 'https://upload.wikimedia.org/wikipedia/commons/8/8d/Ch%C3%A2teau_Frontenac_02.jpg', 'Bernard Gagnon (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#3b5266,#1c2c38)')
