INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('copacabana-palace-rio', 'Copacabana Palace, A Belmond Hotel', 'Rio de Janeiro', '🏖️', 'Brazil', 'Action', '🎯', '1970s', ARRAY['Moonraker']::text[], 'Roger Moore''s 007 stays at this iconic Copacabana Beach hotel during the film''s Rio de Janeiro sequence, a confirmed on-location Bond filming site.', 'Opened in 1923 on Copacabana Beach, the Copacabana Palace is Rio''s most famous hotel. Its white façade and pool have welcomed film stars for a century and made it a natural stop for Moonraker.', 'https://www.booking.com/hotel/br/copacabana-palace.html', 'https://upload.wikimedia.org/wikipedia/commons/7/7a/Copacabana_Palace_-_Rio_de_Janeiro_-_20240709110621.jpg', 'Joalpe (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#e8d8b8,#a8885a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('ciragan-palace-kempinski-istanbul', 'Çırağan Palace Kempinski Istanbul', 'Istanbul', '🕌', 'Turkey', 'Action', '🕶️', '2010s', ARRAY['Skyfall']::text[], 'This former Ottoman palace on the Bosphorus served as Bond''s refuge in Skyfall, with its infinity pool used for 007''s recovery scenes.', 'Completed in 1871 as an Ottoman imperial palace on the Bosphorus, the Çırağan later became a luxury hotel. Its waterfront terraces and infinity pool give Skyfall its Istanbul-era mood.', 'https://www.booking.com/hotel/tr/ciragan-palace-kempinski-istanbul.html', 'https://upload.wikimedia.org/wikipedia/commons/7/74/Ciragan_Palace_2014.JPG', 'Moroder (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#5a7a8a,#2e4a56)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('gstaad-palace', 'Gstaad Palace', 'Gstaad', '🏔️', 'Switzerland', 'Comedy', '😂', '1970s', ARRAY['The Return of the Pink Panther', 'The Palace']::text[], 'Exterior shots of the Swiss chalet-style hotel appear in Peter Sellers'' 1975 The Return of the Pink Panther, and Roman Polanski shot his 2023 film The Palace here.', 'Opened in 1913, the Gstaad Palace is a castle-like hotel above the Swiss resort of Gstaad that has hosted film stars and royals. Its chalet-castle silhouette is what you see in the Pink Panther films.', 'https://www.booking.com/hotel/ch/gstaad-palace.html', 'https://upload.wikimedia.org/wikipedia/commons/9/92/The_Gstaad_Palace.jpg', 'Samuel Barlow (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#6f8fa8,#34506a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('old-cataract-aswan', 'Sofitel Legend Old Cataract Aswan', 'Aswan', '🏜️', 'Egypt', 'Thriller', '🔪', '1970s', ARRAY['Death on the Nile']::text[], 'The 1978 Agatha Christie adaptation was shot at this Nile-side hotel, which also inspired the novel''s setting; Poirot''s Aswan scenes play out on its terraces.', 'Opened in 1899 on a rocky bluff above the Nile, the Old Cataract is among Egypt''s most storied hotels. Agatha Christie wrote part of Death on the Nile here, and the 1978 film shot on its terraces.', 'https://www.booking.com/hotel/eg/sohitel-legend-old-cataract.html', 'https://upload.wikimedia.org/wikipedia/commons/7/7a/Old_Cataract_Hotel_Aswan_%D9%81%D9%86%D8%AF%D9%82_%D9%83%D8%AA%D8%B1%D8%A7%D9%83%D8%AA.jpg', 'Ahmed Emad H (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#d9a35f,#8a5a2b)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('carlton-cannes', 'Carlton Cannes, a Regent Hotel', 'Cannes', '🎞️', 'France', 'Romance', '💕', '1950s', ARRAY['To Catch a Thief', 'French Kiss']::text[], 'Hitchcock used the Carlton and its Croisette setting for Cary Grant and Grace Kelly''s Riviera romance in 1955, and large parts of the 1995 romcom French Kiss were filmed in and around the hotel.', 'Opened in 1911 on the Croisette in Cannes, the Carlton is a Belle Époque landmark with twin domes. Its seafront setting made it a natural for the Riviera glamour of To Catch a Thief and French Kiss.', 'https://www.booking.com/hotel/fr/intercontinental-carlton-cannes.html', 'https://upload.wikimedia.org/wikipedia/commons/1/1b/Cannes_-_hotel_CARLTON.jpg', 'Christophe.Finot (Wikimedia Commons, CC BY-SA 2.5)', 'linear-gradient(135deg,#4a90b8,#1f4e6e)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('westin-grand-berlin', 'The Westin Grand Berlin', 'Berlin', '🐻', 'Germany', 'Action', '💥', '2000s', ARRAY['The Bourne Supremacy']::text[], 'Jason Bourne walks through the hotel''s grand foyer and up its sweeping staircase to reach CIA official Pamela Landy''s suite.', 'Opened in 1987 on Friedrichstrasse in central Berlin, the Westin Grand is known for its sweeping lobby staircase. That staircase is exactly what Jason Bourne climbs in The Bourne Supremacy.', 'https://www.booking.com/hotel/de/westingrand.html', 'https://upload.wikimedia.org/wikipedia/commons/0/0c/Berlin,_Mitte,_Friedrichstrasse_157-164,_Westin_Grand.jpg', 'Jörg Zägel (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#5b6575,#2a303a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('st-pancras-renaissance-london', 'St Pancras Renaissance Hotel London', 'London', '🎡', 'United Kingdom', 'Action', '🦇', '2000s', ARRAY['Batman Begins', 'The Secret Garden']::text[], 'The Gothic Revival former Midland Grand Hotel doubled for Arkham Asylum''s stairwell in Batman Begins (2005), and its grand staircase also served as Mistlethwaite Manor in The Secret Garden (1993).', 'Opened as the Midland Grand Hotel in 1873 and restored as a hotel in 2011, this Gothic Revival masterpiece fronts St Pancras station. Its grand staircase and red-brick spires have given films a ready-made Gothic setting.', 'https://www.booking.com/hotel/gb/renaissance-st-pancras-london.en-gb.html', 'https://upload.wikimedia.org/wikipedia/commons/3/30/St_Pancras_Renaissance_London_Hotel_2011-06-19.jpg', 'LepoRello (Wikimedia Commons, CC BY-SA 3.0)', 'linear-gradient(135deg,#9a4a3a,#55241c)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('marina-bay-sands-singapore', 'Marina Bay Sands', 'Singapore', '🦁', 'Singapore', 'Romance', '💕', '2010s', ARRAY['Crazy Rich Asians']::text[], 'The 57th-floor SkyPark and its record-size rooftop infinity pool star in Crazy Rich Asians (2018), setting the stage for the film''s glittering engagement party.', 'Opened in 2010 and designed by Moshe Safdie, Marina Bay Sands is three towers topped by a ship-shaped SkyPark. Its rooftop infinity pool is the signature image of Crazy Rich Asians.', 'https://www.booking.com/hotel/sg/marina-bay-sands.html', 'https://upload.wikimedia.org/wikipedia/commons/a/a3/Marina_Bay_Sands_Singapore_by_day.jpg', 'Medtd1 (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#2a9d8f,#1b4d5c)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('beverly-hills-hotel', 'The Beverly Hills Hotel', 'Beverly Hills', '🌴', 'United States', 'Comedy', '😂', '1980s', ARRAY['Troop Beverly Hills']::text[], 'The ''Pink Palace'' on Sunset Boulevard is the glamorous backdrop for Troop Beverly Hills (1989), where the Wilderness Girls troop camps in a hotel bungalow.', 'Opened in 1912 and known as the Pink Palace, the Beverly Hills Hotel has long been a hangout for the entertainment business. Its pink exterior, palm-lined drive and bungalows are the setting of Troop Beverly Hills.', 'https://www.booking.com/hotel/us/the-beverly-hills.html', 'https://upload.wikimedia.org/wikipedia/commons/4/47/The_Beverly_Hills_Hotel_(2013).jpg', 'Alan Light (Wikimedia Commons, CC BY 2.0)', 'linear-gradient(135deg,#f4a6b8,#b8567a)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('hotel-de-paris-monte-carlo', 'Hôtel de Paris Monte-Carlo', 'Monte Carlo', '🎰', 'Monaco', 'Action', '🦇', '1990s', ARRAY['GoldenEye', 'Never Say Never Again']::text[], 'Standing beside the Casino de Monte-Carlo, this Belle Époque hotel appears in the James Bond films Never Say Never Again (1983) and GoldenEye (1995).', 'Opened in 1864 beside the Casino de Monte-Carlo, the Hôtel de Paris is the symbol of Monaco''s Belle Époque glamour. Its location on the casino square made it a natural fit for James Bond''s Riviera scenes.', 'https://www.booking.com/hotel/mc/ha-tel-de-paris.html', 'https://upload.wikimedia.org/wikipedia/commons/d/d5/2016_Hotel_de_Paris_-_Monaco_01.jpg', 'Jordiferrer (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#c9a24b,#6b4f17)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('raffles-singapore', 'Raffles Singapore', 'Singapore', '🦁', 'Singapore', 'Romance', '💕', '2010s', ARRAY['Crazy Rich Asians']::text[], 'The colonial-era landmark plays the fictional Kingsford Hotel in Crazy Rich Asians (2018), where Nick and Rachel stay when she isn''t welcome at his family''s home.', 'Opened in 1887 and named after Sir Stamford Raffles, the hotel was gazetted a national monument in 1987. Its Long Bar is where the Singapore Sling cocktail is said to have been invented.', 'https://www.booking.com/hotel/sg/raffles.html', 'https://upload.wikimedia.org/wikipedia/commons/6/63/Front_facade_of_Raffles_Hotel,_Singapore,_from_southeast.jpg', 'Daniel Case (Wikimedia Commons, CC BY-SA 4.0)', 'linear-gradient(135deg,#d9c9a3,#8a7a52)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

INSERT INTO hotels (id, name, city, city_emoji, country, genre, genre_emoji, era, movies, scene, story, booking_url, photo, photo_credit, photo_gradient)
VALUES ('plaza-athenee-paris', 'Hôtel Plaza Athénée', 'Paris', '🗼', 'France', 'Romance', '💕', '2000s', ARRAY['Sex and the City', 'Something''s Gotta Give', 'Emily in Paris']::text[], 'Carrie Bradshaw stays at the Plaza Athénée in the Paris finale of Sex and the City, with its Eiffel Tower balcony view; the hotel also appears in Something''s Gotta Give and Emily in Paris.', 'Opened in April 1913 on Avenue Montaigne, the Plaza Athénée has a classically French main building topped by Art Deco upper floors. Its red window awnings and geranium-filled window boxes make it easy to spot.', 'https://www.booking.com/hotel/fr/ha-tel-plaza-atha-c-na-c-e-paris.html', 'https://upload.wikimedia.org/wikipedia/commons/5/58/Facade_of_the_H%C3%B4tel_Plaza_Ath%C3%A9n%C3%A9e,_Paris_17_July_2017.jpg', 'Joe deSousa (Wikimedia Commons, CC0)', 'linear-gradient(135deg,#c9585f,#7a2e3b)')
ON CONFLICT (id) DO UPDATE SET story = EXCLUDED.story;

